 const fixed=new THREE.Group();fixed.name='NBIoT-CN antenna fixed coupling,neck,fork andaxle';this.body.add(fixed);const black=materials.plastic(0x151a16,{roughness:.84}),rib=materials.plastic(0x282c25,{roughness:.88}),metal=materials.metal(0xb7b9aa,{roughness:.44}),gold=materials.metal(0xc3ac65),ptfe=materials.plastic(0xe1dfc9),nut=ringY(fixed,4.8,3.35,8.2,-5,black,'NBIoT-CN antenna real bored male coupling nut'),lip=ringY(fixed,3.95,3.35,.4,-5,metal,'NBIoT-CN antenna open metal coupling lip');
